  // Door knock — knuckles on a heavy cellar door. Times defaults to 3.
  // REBUILT 2026-09-12 (Sam: "it doesn't sound like a knock at all"). The old
  // one was a 5ms noise burst bandpassed hard at 380Hz plus a single sine, so
  // everything above 400Hz was thrown away and it read as a tick, not a rap.
  // What actually makes a knock legible:
  //   1. a broadband knuckle crack with real HF in it, rolled off at the top so
  //      it is wood and not a stick on tile;
  //   2. the panel answering on SEVERAL modes at once, not one sine, the lowest
  //      hanging longest;
  //   3. a short thud through the frame, felt more than heard;
  //   4. a little of the stairwell behind it, because this door is below ground;
  //   5. per-rap variation, so three raps are not one rap three times.
  function doorKnock(times) {
    times = times || 3;
    _play(function(ac) {
      var now = ac.currentTime;
      for (var k = 0; k < times; k++) {
        var t = now + k * 0.19;
        var vary = 0.92 + Math.random() * 0.16;   // pitch/weight of this rap
        var hit  = 0.88 + Math.random() * 0.24;   // how hard it landed

        // 1. The knuckle itself: a very short crack, band-limited to wood.
        var nLen = Math.floor(ac.sampleRate * 0.06);
        var nb = ac.createBuffer(1, nLen, ac.sampleRate);
        var nd = nb.getChannelData(0);
        for (var i = 0; i < nLen; i++) {
          nd[i] = (Math.random() * 2 - 1) * Math.exp(-i / (ac.sampleRate * 0.0038));
        }
        var nsrc = ac.createBufferSource(); nsrc.buffer = nb;
        var lp = ac.createBiquadFilter(); lp.type = 'lowpass';
        lp.frequency.value = 2700 * vary; lp.Q.value = 0.6;
        var hp = ac.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 200;
        var ng = ac.createGain(); ng.gain.value = 0.34 * hit;
        nsrc.connect(lp); lp.connect(hp); hp.connect(ng); ng.connect(ac.destination);
        nsrc.start(t);

        // 2. The panel: three modes, the low one hanging longest.
        var modes = [[94, 0.24, 0.30], [151, 0.15, 0.18], [237, 0.085, 0.12]];
        for (var m = 0; m < modes.length; m++) {
          var f0 = modes[m][0] * vary, amp = modes[m][1] * hit, dur = modes[m][2];
          var o = ac.createOscillator(); o.type = 'sine';
          o.frequency.setValueAtTime(f0 * 1.07, t);
          o.frequency.exponentialRampToValueAtTime(f0, t + 0.045);
          var og = ac.createGain();
          og.gain.setValueAtTime(0.0001, t);
          og.gain.linearRampToValueAtTime(amp, t + 0.004);
          og.gain.exponentialRampToValueAtTime(0.0008, t + dur);
          o.connect(og); og.connect(ac.destination);
          o.start(t); o.stop(t + dur + 0.03);
        }

        // 3. The frame taking it: a short low thud under everything.
        var th = ac.createOscillator(); th.type = 'sine';
        th.frequency.setValueAtTime(62 * vary, t);
        th.frequency.exponentialRampToValueAtTime(44 * vary, t + 0.09);
        var thg = ac.createGain();
        thg.gain.setValueAtTime(0.0001, t);
        thg.gain.linearRampToValueAtTime(0.20 * hit, t + 0.006);
        thg.gain.exponentialRampToValueAtTime(0.0008, t + 0.13);
        th.connect(thg); thg.connect(ac.destination);
        th.start(t); th.stop(t + 0.15);

        // 4. The stairwell behind the door: a quiet filtered tail so the rap
        //    sounds like it is landing on something with a cellar behind it.
        var rLen = Math.floor(ac.sampleRate * 0.28);
        var rb = ac.createBuffer(1, rLen, ac.sampleRate);
        var rd = rb.getChannelData(0);
        for (var j = 0; j < rLen; j++) {
          rd[j] = (Math.random() * 2 - 1) * Math.exp(-j / (ac.sampleRate * 0.075));
        }
        var rsrc = ac.createBufferSource(); rsrc.buffer = rb;
        var rf = ac.createBiquadFilter(); rf.type = 'bandpass';
        rf.frequency.value = 430 * vary; rf.Q.value = 1.1;
        var rg = ac.createGain(); rg.gain.value = 0.055 * hit;
        rsrc.connect(rf); rf.connect(rg); rg.connect(ac.destination);
        rsrc.start(t + 0.012);
      }
    });
  }
  // Lily chime — held string-harmonic note that swells and fades.
  // Played when the player clicks one of the lily-flower glimpses.
  // Pitched an octave down from the original (E6 → E5) so it reads as
