  var bk = seeded(Math.floor(c / 7), Math.floor(r / 9), 13);
  var base = v < 0.34 ? PAL.brick : (v < 0.67 ? PAL.stucco : PAL.brick2);
  if (bk > 0.74) base = v < 0.5 ? '#31211a' : '#2b1e19'; else if (bk < 0.2) base = v < 0.5 ? '#25282e' : '#212429';
  x.fillStyle = base; x.fillRect(0, 0, T, T);
