  var w = litCol ? (seeded(c,r,5) > 0.45 ? lighten(litCol, 0.35) : lighten(litCol, 0.1)) : (seeded(c,r,6) > 0.74 ? PAL.winWarm : PAL.winDark);
  // the red rooms: only on the old trade's streets, never a venue front, a few to a block
  var redZone = (c <= 8 && r >= 24 && r <= 40) || ((r === 26 || r === 29) && c >= 7 && c <= 40) || (r >= 29 && r <= 34 && c >= 19 && c <= 28);
  if (!litCol && redZone && !doorAt(c, r) && seeded(c, r, 11) > 0.8) { w = PAL.winRed; RED_WINS.push({ x: c*T + (seeded(c,r,12) > 0.5 ? 3 : 10), y: r*T + 3, k: RED_WINS.length }); }
  x.fillStyle = w; x.fillRect(3, 3, 3, 4); x.fillRect(10, 3, 3, 4);
  if (w === PAL.winWarm && WIN_BLINK.length < 24 && seeded(c,r,7) > 0.5) WIN_BLINK.push({x: c*T + (seeded(c,r,8) > 0.5 ? 3 : 10), y: r*T + 3, k: WIN_BLINK.length});
  if (w === PAL.winWarm) WARM_WINS.push({ x: c*T, y: r*T, u: seeded(c, r, 9) }); // bedtime: this window goes dark once the night is u of the way through
  x.fillStyle = (w === PAL.winDark || w === PAL.winRed) ? PAL.winGlass : w; x.fillRect(3, 10, 3, 4); x.fillRect(10, 10, 3, 4);
  x.fillStyle = PAL.soot; x.fillRect(3, 5, 3, 1); x.fillRect(10, 5, 3, 1);
