  if (!LEDGER_ON) return '';
  if (!link || !link.compareDocumentPosition) return '';
  var scope = link.parentElement;
  while (scope && scope.tagName !== 'TW-HOOK' && scope.tagName !== 'TW-PASSAGE') scope = scope.parentElement;
  if (!scope) return '';
  var FOLLOWING = 4;   // Node.DOCUMENT_POSITION_FOLLOWING
  var anchors = scope.querySelectorAll('tw-link, .greyed-out'), next = null;
  for (var i = 0; i < anchors.length; i++) {
    if (anchors[i] === link) { next = anchors[i + 1] || null; break; }
  }
  var out = '', pips = scope.querySelectorAll('span.hp, span.op, span.pp, span.lp, span.al, span.qp');
  for (var j = 0; j < pips.length; j++) {
    var s = pips[j];
    if (!(link.compareDocumentPosition(s) & FOLLOWING)) continue;          // sits before this door
    if (next && (next.compareDocumentPosition(s) & FOLLOWING)) continue;   // belongs to the next door
    out += s.outerHTML;
  }
