    var btn = document.createElement('button'); btn.type = 'button'; btn.textContent = b[3]; btn.setAttribute('aria-label', 'Walk ' + b[0]);
    btn.style.gridColumn = b[1]; btn.style.gridRow = b[2]; btn.setAttribute('data-dir', b[0]);
    dpad.appendChild(btn);
