  this.card.appendChild(sep);
  var canvasWrap = document.createElement('div');
  canvasWrap.style.cssText = 'position:relative;z-index:2;padding:18px 28px 0;';
  this.card.appendChild(canvasWrap);
  this.canvas = document.createElement('canvas');
  this.canvas.width = 320;   // 2x backing store — the old 1x canvas looked soft
  this.canvas.height = 400;
  this.canvas.style.cssText = 'cursor:pointer;display:block;width:160px;height:200px;';
  this.ctx = this.canvas.getContext('2d');
  this.ctx.setTransform(2, 0, 0, 2, 0, 0);
  canvasWrap.appendChild(this.canvas);
  this.prompt = document.createElement('div');
  this.prompt.style.cssText = 'position:relative;z-index:2;margin-top:10px;font:italic 13px Georgia,serif;color:rgba(212,165,116,0.75);letter-spacing:0.04em;';
