            x: 104 + (Math.random() - 0.5) * 8,
            y: 162,
            vx: -8 - Math.random() * 30,
            vy: -22 - Math.random() * 26,
            life: 0.9,
            size: 1.0 + Math.random() * 1.6,
            col: Math.random() < 0.6 ? '#a8862c' : '#c4a43a'
