    c.fillStyle = 'rgba(8,9,7,0.55)'; c.fillRect(0, 132, W, H - 132);
    // Overhead lamp pool
    g = c.createRadialGradient(80, 4, 4, 80, 4, 95);
    g.addColorStop(0, 'rgba(214,188,120,0.13)'); g.addColorStop(1, 'rgba(0,0,0,0)');
    c.fillStyle = g; c.fillRect(0, 0, W, H);
