if (!jewels.length) jewels = document.querySelectorAll('.alba-jewel');
var j = jewels[albaIdx - 1];
if (j) j.classList.add('alba-jewel-filled');
// 2026-10-14 (regression run: two stars beside "1/3" in the Cave): the count and the line under the header follow
