  fgS.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:3;mix-blend-mode:screen;opacity:0.06;' +
    'background-image:radial-gradient(ellipse 34% 46% at 50% 50%, rgba(255,236,200,1), transparent 70%),' +
    'radial-gradient(ellipse 30% 40% at 50% 50%, rgba(170,205,255,.85), transparent 70%);' +
    'background-size:170% 170%,190% 190%;background-repeat:no-repeat;' +
    'animation:dssShimmerDrift 31s ease-in-out infinite alternate;';
