    window.removeEventListener('resize', resize);
    if (observer) observer.disconnect();
    if (loader) { loader.onload = loader.onerror = null; loader.remove(); }
    if (scene) {
      var geos = new Set(), mats = new Set(), maps = new Set();
      scene.traverse(function(o) {
        if (o.geometry) geos.add(o.geometry);
        if (o.material) (Array.isArray(o.material) ? o.material : [o.material]).forEach(function(m) {
          mats.add(m); if(m.map) maps.add(m.map);
        });
      });
      geos.forEach(function(g){g.dispose();}); maps.forEach(function(t){t.dispose();});
      mats.forEach(function(m){m.dispose();});
    }
    if (renderer) { renderer.dispose(); renderer.forceContextLoss(); }
