var catFurTex=makeCanvasTexture(512,256,function(cx,w,h){
 cx.fillStyle='#a86c38';cx.fillRect(0,0,w,h);
 var shade=cx.createLinearGradient(0,0,0,h);shade.addColorStop(0,'#c18a4d');shade.addColorStop(.5,'#ad7038');shade.addColorStop(1,'#85502c');cx.fillStyle=shade;cx.fillRect(0,0,w,h);
 for(var stripe=0;stripe<12;stripe++){cx.strokeStyle='rgba(70,39,23,.24)';cx.lineWidth=3+stripe%3;for(var fy=0;fy<h;fy+=26){if((fy/26+stripe)%3===0)continue;cx.beginPath();for(var sy=fy;sy<=fy+18;sy+=3){var fx=stripe*w/12+Math.sin(sy*.035+stripe*2)*7;if(sy===fy)cx.moveTo(fx,sy);else cx.lineTo(fx,sy);}cx.stroke();}} /* 2026-10-24 (Sam: the cat "looked a bit weird"): unbroken dark stripes ran pole to pole on the sphere UVs and ribbed the body like a pumpkin; now soft broken tabby flecks */
 var seed=1973;for(var hair=0;hair<2600;hair++){seed=(seed*1664525+1013904223)>>>0;var x=seed/4294967296*w;seed=(seed*1664525+1013904223)>>>0;var y=seed/4294967296*h;cx.strokeStyle=hair%2?'#edcb8a25':'#33251a20';cx.lineWidth=.5;cx.beginPath();cx.moveTo(x,y);cx.lineTo(x+1,y+3);cx.stroke();}
});
