/* 2026-10-24 (Sam: "more majestic and less silly. Maybe longer hair"): shell fur. Each furred volume gets CAT_SHELLS slightly larger copies whose strand mask thins out layer by layer, so the coat reads as long soft hair with a fuzzy edge. Materials are shared per base material and layer. */
var CAT_SHELLS=10;var catStrandTex=makeCanvasTexture(256,256,function(cx,w,h){cx.fillStyle='#000';cx.fillRect(0,0,w,h);var sd=5;function rn(){sd=(sd*16807)%2147483647;return sd/2147483647;}for(var k=0;k<5000;k++){var x=rn()*w,y=rn()*h,g=(60+rn()*195)|0,L=6+rn()*10;var gr=cx.createLinearGradient(0,y,0,y+L);gr.addColorStop(0,'rgb(0,0,0)');gr.addColorStop(1,'rgb('+g+','+g+','+g+')');cx.fillStyle=gr;cx.fillRect(x,y,1.6,L);}}); /* strands run down the sphere meridians and brighten toward their tips, so the outer layers keep only the lower ends: hair that lies down and falls, not bristles */catStrandTex.wrapS=catStrandTex.wrapT=THREE.RepeatWrapping;catStrandTex.repeat.set(3,3);
var catShellMats={};function catShellMat(base,i){var key=base.uuid+'_'+i;if(!catShellMats[key]){var m=base.clone();m.alphaMap=catStrandTex;m.alphaTest=.12+.8*i/CAT_SHELLS;m.color.multiplyScalar(.75+.35*i/CAT_SHELLS);catShellMats[key]=m;}return catShellMats[key];}
function catFurShells(mesh,len,droop,xzOnly){var gp=mesh.geometry.parameters,r=gp.radius||gp.radiusBottom;for(var i=1;i<=CAT_SHELLS;i++){var sh=new THREE.Mesh(mesh.geometry,catShellMat(mesh.material,i));var f=1+len*i/CAT_SHELLS/r;sh.position.copy(mesh.position);sh.position.y-=droop*i/CAT_SHELLS;sh.scale.copy(mesh.scale);if(xzOnly){sh.scale.x*=f;sh.scale.z*=f;}else sh.scale.multiplyScalar(f);mesh.parent.add(sh);}return mesh;}
// Rounded haunches, a narrow chest and the shoulder line of a resting cat.
catFurShells(catScaled(catPart(new THREE.SphereGeometry(.15,20,14),catFurMat,0,.155,-.025),1,1.06,1.26),.03,.01);
catFurShells(catScaled(catPart(new THREE.SphereGeometry(.10,18,12),catFurMat,0,.285,.09),.87,1.4,.85),.06,.02);
