  catTail.rotation.x = Math.sin(t * .6) * .025;
  // Occasional slow head turn between street and phone box
  catState.headTurnT -= catDt;
  if (catState.headTurnT <= 0) {
    catState.headTarget = (Math.random() - 0.4) * 0.8;
    catState.headTurnT = 6 + Math.random() * 9;
  }
  catHead.rotation.y += (catState.headTarget - catHead.rotation.y) * Math.min(1, catDt * 2.2);
  // Blink: eyes wink out for a beat
  catState.blinkT -= catDt;
  if (catState.blinkT <= 0) {
    catState.blinkHold = 0.14;
    catState.blinkT = 3 + Math.random() * 5;
  }
  if (catState.blinkHold > 0) {
    catState.blinkHold -= catDt;
    eyeL.visible = eyeR.visible = false;
  } else {
    eyeL.visible = eyeR.visible = true;
  }

