lostLong = lostNow; lostTurned = true;
box.classList.toggle('dss-room-prose-lost', lostLong);
strip.classList.toggle('dss-room-strip-lost', lostLong);
var c = wrap.querySelector('.dss-room-card');
if (c) { c.style.opacity = lostLong ? '0' : c.style.opacity; if (lostLong) c.style.pointerEvents = 'none'; }
