var keysTimer = setInterval(function() { if (!wrap.isConnected) { clearInterval(keysTimer); document.removeEventListener('keydown', onEsc); wrap.removeEventListener('dss-room-key-entry',enterRoomByKey); if(roomLayoutObserver)roomLayoutObserver.disconnect(); else window.removeEventListener('resize',reflowCard); return; } keysRefresh(); }, 250);
