piVig.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:9001;background:radial-gradient(ellipse at 50% 44%,transparent 34%,rgba(0,0,0,0.48) 100%);';
piWrap.appendChild(piVig);
