for (var li = 0; li < lamps.length; li++) { var br = 0.035 * Math.sin(t * (0.6 + li * 0.13) + li) + 0.018 * Math.sin(t * 0.19 + li * 2); lamps[li].intensity = 1.0 + br; glows[li].material.opacity = 0.55 + br * 0.6; haze[li].material.opacity = 0.12 + br * 0.2; }
