// Lush greenery — painted leafy clumps, layered and irregular, not solid blobs
var leafClumpTex = makeCanvasTexture(96, 96, function(cx, w, h) {
  var greens = ['#1e4410', '#2a5a1a', '#39702a', '#4a8230', '#254e14'];
  for (var lf = 0; lf < 70; lf++) {
    var la = Math.random() * Math.PI * 2;
    var lr = Math.random() * Math.random() * w * 0.42;
    var lx = w / 2 + Math.cos(la) * lr;
    var ly = h / 2 + Math.sin(la) * lr * 0.8;
    // Darker leaves toward the bottom of the clump for baked shading
    var gi = Math.floor(Math.random() * greens.length);
    if (ly > h * 0.6 && gi > 1) gi -= 2;
    cx.fillStyle = greens[gi];
    cx.save();
    cx.translate(lx, ly);
    cx.rotate(Math.random() * Math.PI);
    cx.beginPath();
    cx.ellipse(0, 0, 3 + Math.random() * 5, 2 + Math.random() * 3, 0, 0, Math.PI * 2);
    cx.fill();
    cx.restore();
  }
});
for (var li = -1.25; li <= 3.85; li += 0.26) {
  var clumpMat = new THREE.SpriteMaterial({ map: leafClumpTex, transparent: true, depthWrite: false });
  clumpMat.color.setScalar(0.75 + Math.random() * 0.35);
  var clump = new THREE.Sprite(clumpMat);
  var cs = 0.55 + Math.random() * 0.35;
  clump.scale.set(cs, cs * (0.7 + Math.random() * 0.3), 1);
  clump.position.set(li + (Math.random() - 0.5) * 0.1, 4.32 + Math.random() * 0.2, 0.62 + Math.random() * 0.18);
  pub.add(clump);
}
// Trailing strands spilling down over the fascia edge
var strandTex = makeCanvasTexture(32, 96, function(cx, w, h) {
  var sGreens = ['#1e4410', '#2a5a1a', '#39702a'];
  var sx0 = w / 2;
  for (var sl = 0; sl < 9; sl++) {
    var sy = 4 + sl * (h - 10) / 9;
    var sx = sx0 + Math.sin(sl * 0.9) * 5;
    cx.fillStyle = sGreens[sl % sGreens.length];
    cx.save();
    cx.translate(sx, sy);
    cx.rotate(0.5 + Math.sin(sl * 1.7) * 0.6);
    cx.beginPath();
    cx.ellipse(0, 0, 4.2, 2.4, 0, 0, Math.PI * 2);
    cx.fill();
    cx.restore();
    // Stem hint
    cx.strokeStyle = 'rgba(26, 58, 14, 0.7)'; cx.lineWidth = 1.2;
    cx.beginPath(); cx.moveTo(sx0 + Math.sin(sl * 0.9) * 5, sy);
    cx.lineTo(sx0 + Math.sin((sl + 1) * 0.9) * 5, sy + (h - 10) / 9); cx.stroke();
  }
});
for (var iv = -1.0; iv <= 3.6; iv += 0.55) {
  var strandMat = new THREE.SpriteMaterial({ map: strandTex, transparent: true, depthWrite: false });
  strandMat.color.setScalar(0.7 + Math.random() * 0.3);
  var strand = new THREE.Sprite(strandMat);
  strand.scale.set(0.16 + Math.random() * 0.06, 0.42 + Math.random() * 0.28, 1);
  strand.position.set(iv + (Math.random() - 0.5) * 0.2, 3.62 - Math.random() * 0.12, 0.58);
  pub.add(strand);
}

