// Layout: [left bay] [door] [right bay 1] [right bay 2]
// Pub front runs from x=-1.05 to x=4.0

// Painted Victorian pub interior — back bar, bottles, tankards, drinkers
function makePillarsInteriorTex(seed) {
  return makeCanvasTexture(256, 288, function(cx2, w, h) {
    cx2.fillStyle = '#281605'; cx2.fillRect(0, 0, w, h);
    var rg = cx2.createRadialGradient(w * (0.3 + seed * 0.4), h * 0.35, 10, w / 2, h * 0.45, w * 0.85);
    rg.addColorStop(0, 'rgba(255, 200, 100, 0.6)');
    rg.addColorStop(0.5, 'rgba(210, 140, 50, 0.32)');
    rg.addColorStop(1, 'rgba(100, 60, 20, 0.08)');
    cx2.fillStyle = rg; cx2.fillRect(0, 0, w, h);
    // Nicotine ceiling band
    cx2.fillStyle = 'rgba(130, 90, 40, 0.4)';
    cx2.fillRect(0, 0, w, h * 0.1);
    // Hanging tankards and glasses along a rail
    for (var tk = 0; tk < 6; tk++) {
      var tkx = w * 0.1 + tk * w * 0.15;
      cx2.strokeStyle = 'rgba(200, 170, 110, 0.55)'; cx2.lineWidth = 2;
      cx2.beginPath(); cx2.moveTo(tkx, h * 0.1); cx2.lineTo(tkx, h * 0.16); cx2.stroke();
      cx2.fillStyle = tk % 2 ? 'rgba(190, 160, 90, 0.6)' : 'rgba(225, 215, 185, 0.45)';
      cx2.fillRect(tkx - 4, h * 0.16, 8, h * 0.05);
    }
    // Back-bar mirror with glint
    cx2.fillStyle = 'rgba(145, 125, 90, 0.45)';
    cx2.fillRect(w * 0.1, h * 0.24, w * 0.8, h * 0.2);
    cx2.fillStyle = 'rgba(235, 215, 170, 0.22)';
    cx2.beginPath();
    cx2.moveTo(w * (0.2 + seed * 0.2), h * 0.24); cx2.lineTo(w * (0.32 + seed * 0.2), h * 0.24);
    cx2.lineTo(w * (0.2 + seed * 0.2), h * 0.44); cx2.lineTo(w * (0.08 + seed * 0.2), h * 0.44);
    cx2.closePath(); cx2.fill();
    // Bottle row on the shelf
    var pbCols = ['#2a4a2a', '#5a3a18', '#1a2a4a', '#6a5a20', '#3a1a1a'];
    for (var pb2 = 0; pb2 < 8; pb2++) {
      cx2.fillStyle = pbCols[(pb2 + Math.floor(seed * 4)) % pbCols.length];
      var pbx = w * 0.13 + pb2 * w * 0.095;
      cx2.fillRect(pbx, h * 0.34, w * 0.038, h * 0.1);
      cx2.fillRect(pbx + w * 0.012, h * 0.31, w * 0.015, h * 0.035);
    }
    cx2.fillStyle = 'rgba(55, 35, 14, 0.9)';
    cx2.fillRect(w * 0.08, h * 0.44, w * 0.84, h * 0.018);
    // Bar counter with brass rail
    cx2.fillStyle = 'rgba(75, 48, 20, 0.95)';
    cx2.fillRect(0, h * 0.56, w, h * 0.05);
    cx2.fillStyle = 'rgba(200, 165, 80, 0.5)';
    cx2.fillRect(0, h * 0.555, w, h * 0.008);
    // Pump handles on the counter
    for (var ph2 = 0; ph2 < 3; ph2++) {
      cx2.fillStyle = 'rgba(40, 22, 10, 0.9)';
      cx2.fillRect(w * (0.25 + ph2 * 0.2 + seed * 0.05), h * 0.48, 4, h * 0.08);
      cx2.fillStyle = 'rgba(220, 205, 175, 0.8)';
      cx2.beginPath(); cx2.arc(w * (0.25 + ph2 * 0.2 + seed * 0.05) + 2, h * 0.475, 4, 0, Math.PI * 2); cx2.fill();
    }
    // Drinkers at the bar — dark head-and-shoulder silhouettes
    var figN = 1 + Math.floor(seed * 2.2);
    for (var fg2 = 0; fg2 < figN; fg2++) {
      var fgx = w * (0.22 + fg2 * 0.42 + seed * 0.1);
      cx2.fillStyle = 'rgba(12, 6, 2, 0.88)';
      cx2.beginPath(); cx2.arc(fgx, h * 0.6, w * 0.055, 0, Math.PI * 2); cx2.fill();
      cx2.beginPath();
      cx2.ellipse(fgx, h * 0.76, w * 0.11, h * 0.13, 0, Math.PI, 0, true);
      cx2.fill();
      cx2.fillRect(fgx - w * 0.11, h * 0.76, w * 0.22, h * 0.24);
      // A raised glass for the first
      if (fg2 === 0 && seed > 0.3) {
        cx2.fillRect(fgx + w * 0.12, h * 0.62, w * 0.035, h * 0.06);
        cx2.fillStyle = 'rgba(210, 150, 60, 0.6)';
        cx2.fillRect(fgx + w * 0.125, h * 0.63, w * 0.025, h * 0.035);
      }
    }
    // Etched frosted band across the lower glass — Victorian pub privacy glass
    cx2.fillStyle = 'rgba(235, 230, 215, 0.32)';
    cx2.fillRect(0, h * 0.82, w, h * 0.18);
    cx2.strokeStyle = 'rgba(255, 252, 240, 0.4)'; cx2.lineWidth = 2;
    cx2.beginPath(); cx2.moveTo(0, h * 0.82); cx2.lineTo(w, h * 0.82); cx2.stroke();
    for (var et = 0; et < 4; et++) {
      cx2.beginPath();
      cx2.arc(w * (0.125 + et * 0.25), h * 0.91, w * 0.06, 0, Math.PI * 2);
      cx2.stroke();
    }
  });
}

// Helper: create a proper pub window bay
function createWindowBay(cx, bayW, bayH, yBase) {
  var glassH = bayH - 0.5; // glass area (above kickboard)
  var glassY = yBase + 0.25 + glassH / 2;
  var kickY = yBase + 0.17;

  // The lit interior, painted — with a faint warm glaze over it
  var bayGlass = new THREE.Mesh(new THREE.PlaneGeometry(bayW - 0.12, glassH),
    new THREE.MeshBasicMaterial({ map: makePillarsInteriorTex(((cx * 7.7 + 11) % 10) / 10) }));
  bayGlass.position.set(cx, glassY, 0.63);
  pub.add(bayGlass);
  var bayGlaze = new THREE.Mesh(new THREE.PlaneGeometry(bayW - 0.12, glassH),
    new THREE.MeshBasicMaterial({ color: 0xffd699, transparent: true, opacity: 0.16 }));
  bayGlaze.position.set(cx, glassY, 0.645);
  pub.add(bayGlaze);

  // Outer frame (mahogany surround)
  placeMesh(pub, new THREE.BoxGeometry(0.06, bayH, 0.08), mahogany, cx - bayW/2, yBase + bayH/2, 0.62);
  placeMesh(pub, new THREE.BoxGeometry(0.06, bayH, 0.08), mahogany, cx + bayW/2, yBase + bayH/2, 0.62);
  placeMesh(pub, new THREE.BoxGeometry(bayW + 0.06, 0.06, 0.08), mahogany, cx, yBase + bayH, 0.62);
  placeMesh(pub, new THREE.BoxGeometry(bayW + 0.06, 0.06, 0.08), mahogany, cx, yBase + 0.5, 0.62);

  // Vertical glazing bars (dividing bay into 3 panes)
  var paneW = bayW / 3;
  placeMesh(pub, new THREE.BoxGeometry(0.03, glassH, 0.04), mahogany, cx - paneW / 2 - paneW / 6, glassY, 0.66);
  placeMesh(pub, new THREE.BoxGeometry(0.03, glassH, 0.04), mahogany, cx + paneW / 2 + paneW / 6, glassY, 0.66);

  // Horizontal glazing bars (2 rows for traditional 3×3 grid effect)
  var thirdH = glassH / 3;
  placeMesh(pub, new THREE.BoxGeometry(bayW - 0.12, 0.03, 0.04), mahogany, cx, glassY - thirdH / 2, 0.66);
  placeMesh(pub, new THREE.BoxGeometry(bayW - 0.12, 0.03, 0.04), mahogany, cx, glassY + thirdH / 2, 0.66);

  // Solid kickboard panel below glass
  placeMesh(pub, new THREE.BoxGeometry(bayW - 0.08, 0.4, 0.06), mahoganyDark, cx, kickY, 0.62);
  // Kickboard moulding
  placeMesh(pub, new THREE.BoxGeometry(bayW - 0.04, 0.04, 0.04), mahogany, cx, yBase + 0.38, 0.64);
}

