// Window-light on the wet pavement (2026-09-22 polish loop): the three lit
// bays and the door throw a broken amber sheet across the flags in front of
// the pub — strongest at the sill line, fading towards the kerb, cut by the
// paving joints so it reads as reflection, not paint. One additive draw; it
// breathes with pubGlow in phAnimate.
var phSheenTex = makeCanvasTexture(256, 128, function(cx, w, h) {
  var g = cx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, 'rgba(255,196,110,0.6)');
  g.addColorStop(0.45, 'rgba(255,176,86,0.22)');
  g.addColorStop(1, 'rgba(255,160,70,0)');
  cx.fillStyle = g; cx.fillRect(0, 0, w, h);
  var sx = cx.createLinearGradient(0, 0, w, 0);
  sx.addColorStop(0, 'rgba(0,0,0,1)'); sx.addColorStop(0.16, 'rgba(0,0,0,0)');
  sx.addColorStop(0.84, 'rgba(0,0,0,0)'); sx.addColorStop(1, 'rgba(0,0,0,1)');
  cx.globalCompositeOperation = 'destination-out';
  cx.fillStyle = sx; cx.fillRect(0, 0, w, h);
  cx.fillStyle = 'rgba(0,0,0,0.7)';
  for (var ji = 1; ji < 6; ji++) cx.fillRect(0, Math.round(ji * h / 6) - 1, w, 2);
  for (var jj = 1; jj < 8; jj++) cx.fillRect(Math.round(jj * w / 8) - 1, 0, 2, h);
  // the dark bar of the door: the doorway throws less light than the glass
  cx.fillStyle = 'rgba(0,0,0,0.35)';
  cx.fillRect(Math.round(w * 0.30), 0, Math.round(w * 0.09), h);
  cx.globalCompositeOperation = 'source-over';
});
