var streetLampLights = [];
var phDoomLamps = [];

// Pillars streetlamps now use the shared dssScene Victorian gas-
// lamp (4-sided emissive lantern panes so they read as ON at
// low scene brightness). Low point-light intensity keeps the
// surrounding scene dark — only the lantern itself glows.
// 2026-10-14 (speed, Sam: yes): the brothel windows' red spill was seven point lights (21 in this scene made it slow);
// a soft red glow sprite now stands in for each (additive, so it reads as light, not paint)
function piRedSpill(parent, col, x, y, sc) {
  if (!piRedSpill.tex) { var cv = document.createElement('canvas'); cv.width = cv.height = 64; var cx = cv.getContext('2d'); var gr = cx.createRadialGradient(32, 32, 0, 32, 32, 32); gr.addColorStop(0, 'rgba(255,255,255,0.55)'); gr.addColorStop(0.45, 'rgba(255,255,255,0.18)'); gr.addColorStop(1, 'rgba(255,255,255,0)'); cx.fillStyle = gr; cx.fillRect(0, 0, 64, 64); piRedSpill.tex = new THREE.CanvasTexture(cv); }
  var sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: piRedSpill.tex, color: col, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending }));
  sp.position.set(x, y, 0.5); sp.scale.set(sc, sc, 1); parent.add(sp); return sp;
}
function createLamp(x, z) {
  var lamp = window.dssScene.createVictorianGasLamp(scene, x, z, {
    castShadow: false, // 2026-10-14 (speed): nothing here receives its shadow, so the cube shadow was rendered for nothing
    intensity: 0.5, distance: 16,
    haloScale: 2.2, coreScale: 0.9
  });
  // Keep the Pillars flicker animation working
  lamp.userData.light.userData.baseIntensity = 0.5;
  lamp.userData.light.decay = 2; // no hard range terminator on the road
  streetLampLights.push(lamp.userData.light);
  phDoomLamps.push(lamp);
}

createLamp(-4, 3.5);
createLamp(5, 3.5);
createLamp(0, 10);

// Each return kills a lamp: the street lamps first, then the pub's own
// lanterns — the night eats the light as the flood rises.
phDoomLamps = phDoomLamps.concat(lampLightsOnPub);
function phKillLamp(root) {
  root.traverse(function(o) {
    if (o.isSprite && o.material) o.material.opacity = 0;
    else if (o.isMesh && o.material) {
      if (o.material.emissive) o.material.emissiveIntensity = 0;
      if (o.material.isMeshBasicMaterial && o.material.color && (o.material.color.r + o.material.color.g + o.material.color.b) > 1.8) o.material.color.setHex(0x1a1e24);
    }
    if (o.isLight) { o.intensity = 0; o.userData.dead = true; }
  });
}
var phDeadLampCount = Math.min(Math.max(phVisit - 1, 0), phDoomLamps.length);
for (var pdl = 0; pdl < phDeadLampCount; pdl++) phKillLamp(phDoomLamps[pdl]);

