var loRay = new THREE.Raycaster(), loPtr = new THREE.Vector2();
function loHitsCard(ev) {
var rc = renderer.domElement.getBoundingClientRect();
loPtr.set(((ev.clientX - rc.left) / rc.width) * 2 - 1, -((ev.clientY - rc.top) / rc.height) * 2 + 1);
loRay.setFromCamera(loPtr, camera);
return loRay.intersectObjects([modelCard, loMarkCore]).length > 0;
}
renderer.domElement.addEventListener('pointermove', function(ev) { renderer.domElement.style.cursor = (loCardZoom.on || loHitsCard(ev)) ? 'pointer' : ''; });
