  /* 2026-10-29 (Sam's Waterhouse Set): the plain broken drums and the background columns are the weathered marble pillar now, warmed to the dusk;
     the three blue posts, the lintel pair and the skull column stay as built */
  function greyPillar(x, z, h, broken, lean) { if (!window.dssWaterhouse) return buildColumn(x, z, h, broken, lean); var p = window.dssWaterhouse('Grey_Pillar', 0xffe6d4); if (!p) return buildColumn(x, z, h, broken, lean); var full = p.userData.size.y || 5, sc = Math.min(1.1, (broken ? 5.2 : h) / full); p.scale.setScalar(sc); p.position.set(x, 0, z); p.rotation.z = lean || 0; p.rotation.y = x * 0.37; if (broken) { renderer.localClippingEnabled = true; p.children[0].material.clippingPlanes = [new THREE.Plane(new THREE.Vector3(0.12 * Math.sin(x), -1, 0.1 * Math.cos(x)).normalize(), h)]; } scene.add(p); return p; } /* a broken one is the whole pillar cut off at its height, the break canted, not a squashed pillar */
  buildColumn(-10, -3, 5.8, false, 0, blueColumnMat);
