  greyPillar(4, -3, 3.0, true, 0.04);  // broken short — visible next to centre arch
  buildColumn(6, -3, 5.2, false, 0);    // matched to its twin — the pair carries the lintel as a true arch
  buildColumn(8, -3, 5.2, false, 0.02);
  var skullColumn = buildColumn(10, -3, 3.8, true, 0);  // broken — carries the skull

  // ---- THE WATCHING SKULL ----
  // A bleached cattle skull set on the broken stub, horns spread,
  // facing out over the water
  var boneMat = new THREE.MeshStandardMaterial({
    color: 0xe2d6b6, roughness: 0.85,
    emissive: 0x8a7f66, emissiveIntensity: 0.3
  });
  var boneShadow = new THREE.MeshStandardMaterial({ color: 0x2a2018, roughness: 0.9 });
  var skull = new THREE.Group();
  // Cranium — broad and flattened
  var cranium = new THREE.Mesh(new THREE.SphereGeometry(0.16, 10, 8), boneMat);
  cranium.scale.set(1.05, 0.72, 1.2);
  cranium.position.set(0, 0.13, 0);
