  // Long tapering muzzle dropping forward
  var muzzle = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.1, 0.3, 7), boneMat);
  muzzle.rotation.x = Math.PI / 2 - 0.25;
  muzzle.position.set(0, 0.08, 0.22);
  skull.add(muzzle);
  // Nasal hollow at the muzzle tip
  var nasal = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.045, 0.02), boneShadow);
  nasal.rotation.x = -0.25;
  nasal.position.set(0, 0.11, 0.35);
  skull.add(nasal);
  // Hollow eye sockets, wide-set
  var eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.038, 8, 6), boneShadow);
  eyeL.position.set(-0.1, 0.13, 0.11);
  skull.add(eyeL);
  var eyeR = new THREE.Mesh(new THREE.SphereGeometry(0.038, 8, 6), boneShadow);
  eyeR.position.set(0.1, 0.13, 0.11);
  skull.add(eyeR);
  // Cheekbones flaring below the sockets
  var cheekL = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.12), boneMat);
  cheekL.position.set(-0.13, 0.07, 0.1);
  cheekL.rotation.y = 0.3;
  skull.add(cheekL);
  var cheekR = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.12), boneMat);
  cheekR.position.set(0.13, 0.07, 0.1);
  cheekR.rotation.y = -0.3;
  skull.add(cheekR);
  // Horns — curved arcs sweeping out and up from the skull sides
  var hornL = new THREE.Mesh(new THREE.TorusGeometry(0.15, 0.026, 6, 10, Math.PI * 0.72), boneMat);
  hornL.position.set(-0.16, 0.17, -0.02);
  hornL.rotation.set(0.35, 0.5, -1.15);
  skull.add(hornL);
  var hornR = new THREE.Mesh(new THREE.TorusGeometry(0.15, 0.026, 6, 10, Math.PI * 0.72), boneMat);
  hornR.position.set(0.16, 0.17, -0.02);
  hornR.rotation.set(0.35, -0.5, Math.PI + 1.15);
  skull.add(hornR);
