// The Colony's first-floor windows lying on the wet pavement below them:
// one additive plane on top of the raised pavement, two amber pools under
// the lit windows and a green fleck under the right one, cut by flag joints.
var crSheenTex = makeCanvasTexture(256, 96, function(cx, w, h) {
cx.clearRect(0, 0, w, h);
function pool(x, y, rx, ry, col, a) {
var g = cx.createRadialGradient(x, y, 0, x, y, rx);
g.addColorStop(0, col.replace('A', a)); g.addColorStop(0.5, col.replace('A', a * 0.4)); g.addColorStop(1, col.replace('A', 0));
cx.save(); cx.translate(x, y); cx.scale(1, ry / rx); cx.translate(-x, -y);
cx.fillStyle = g; cx.beginPath(); cx.arc(x, y, rx, 0, Math.PI * 2); cx.fill(); cx.restore();
}
pool(w * 0.11, h * 0.4, w * 0.13, h * 0.7, 'rgba(255,200,90,A)', 0.6);
pool(w * 0.54, h * 0.4, w * 0.15, h * 0.75, 'rgba(255,200,90,A)', 0.7);
pool(w * 0.95, h * 0.4, w * 0.08, h * 0.5, 'rgba(150,200,80,A)', 0.35);
cx.strokeStyle = 'rgba(0,0,0,0.5)'; cx.lineWidth = 2;
for (var j = 0; j <= w; j += 37) { cx.beginPath(); cx.moveTo(j, 0); cx.lineTo(j, h); cx.stroke(); }
for (var k = 0; k <= h; k += 32) { cx.beginPath(); cx.moveTo(0, k); cx.lineTo(w, k); cx.stroke(); }
});
