cx.save(); cx.translate(w * 0.555, h * 0.245); cx.rotate(0.25);
cx.beginPath(); cx.ellipse(0, 0, w * 0.035, h * 0.014, 0, 0, Math.PI * 2); cx.fill(); cx.restore();
// Wide muzzle — paler like a real bull's nose
