cx.fillStyle = 'rgba(185, 155, 115, 0.55)';
cx.beginPath(); cx.ellipse(w * 0.46, h * 0.335, w * 0.055, h * 0.026, 0, 0, Math.PI * 2); cx.fill();
// Nostrils — wide-set ovals
