cx.beginPath(); cx.ellipse(w * 0.432, h * 0.335, 4.5, 3, -0.3, 0, Math.PI * 2); cx.fill();
cx.beginPath(); cx.ellipse(w * 0.488, h * 0.335, 4.5, 3, 0.3, 0, Math.PI * 2); cx.fill();
// Horns — thick, spreading outward like a longhorn, slight up-tick at the tips
cx.strokeStyle = '#e0d4ac'; cx.lineWidth = 9; cx.lineCap = 'round';
cx.beginPath(); cx.moveTo(w * 0.4, h * 0.215);
cx.quadraticCurveTo(w * 0.32, h * 0.225, w * 0.27, h * 0.19); cx.stroke();
cx.beginPath(); cx.moveTo(w * 0.52, h * 0.215);
cx.quadraticCurveTo(w * 0.6, h * 0.225, w * 0.65, h * 0.19); cx.stroke();
// Darker horn tips
cx.strokeStyle = '#8a7a50'; cx.lineWidth = 5;
cx.beginPath(); cx.moveTo(w * 0.285, h * 0.2); cx.lineTo(w * 0.27, h * 0.19); cx.stroke();
cx.beginPath(); cx.moveTo(w * 0.635, h * 0.2); cx.lineTo(w * 0.65, h * 0.19); cx.stroke();
cx.lineCap = 'butt';
// Glass eyes — wide-set on the sides of the skull, amber with a glint
cx.fillStyle = '#d08018';
cx.beginPath(); cx.arc(w * 0.415, h * 0.245, 4, 0, Math.PI * 2); cx.fill();
cx.beginPath(); cx.arc(w * 0.505, h * 0.245, 4, 0, Math.PI * 2); cx.fill();
cx.fillStyle = 'rgba(255, 240, 210, 0.95)';
cx.fillRect(w * 0.411, h * 0.238, 2, 2);
cx.fillRect(w * 0.501, h * 0.238, 2, 2);
// Brass nose ring
