// Bollard turned collars
f.ring(0.091,0.012,0x4e4d46,2.2,0.16,2.2);f.ring(0.083,0.009,0x4e4d46,2.2,0.72,2.2);
// Old railing stumps split tops
for(var st=0;st<3;st++){f.box(0.009,0.025,0.02,0x7a6950,-2.5+st*0.3,0.38,0.5);}
// Cast iron pipe joint collars
[0.9,4,7.5,11].forEach(function(y){f.ring(0.045,0.008,0x45443b,0.15,y,0.12);});
// Hopper dark open throat
f.put(new THREE.CircleGeometry(0.083,12),f.mat(0x090b0c),0.15,13.405,0.12).rotation.x=-Math.PI/2;
// Drainpipe shoe mouth
f.box(0.075,0.065,0.003,0x080a0b,0.15,0.17,0.242);f.box(0.1,0.015,0.025,0x47453a,0.15,0.135,0.247,null,true);
// Streetlamp base anchor bolts
[-3,6,-10].forEach(function(x){f.ring(0.17,0.02,0x4b4840,x,0.1,1.8);[-0.12,0.12].forEach(function(dx){f.pin(x+dx,0.12,1.91);});});
