/* 2026-10-29 (Sam: the abstract pack "in the Ronnie's approach"): the sleeves in Cosmogramma's window are psychedelic LP covers now, each its own
   swirl, still dimmed behind the glass, the colour blocks only until they load */
(function() { var A = window.DSS_ABS || {}, keys = ['2','6','13','16','22','26','36','41','44','45','49','50'], cv = recordDisplayTex.image; if (!cv || !cv.getContext) return;
  var cx = cv.getContext('2d'), w = cv.width, h = cv.height, cols = 4, rows = 5, pad = 12, gap = 8, aw = (w - pad * 2 - gap * (cols - 1)) / cols, ah = (h - pad * 2 - gap * (rows - 1)) / rows, k = 0;
  for (var r = 0; r < rows; r++) for (var c = 0; c < cols; c++) (function(ax, ay, src) { if (!src) return; var im = new Image(); im.onload = function() { cx.save(); cx.globalAlpha = 0.6; cx.drawImage(im, ax, ay, aw, ah); cx.globalAlpha = 0.5; cx.fillStyle = 'rgba(255,255,255,0.08)'; cx.fillRect(ax + 2, ay + 2, aw * 0.4, ah * 0.3); cx.restore(); recordDisplayTex.needsUpdate = true; }; im.src = src; })(pad + c * (aw + gap), pad + r * (ah + gap), A[keys[(k++) % keys.length]]);
})();

