wirePts.push(new THREE.Vector3(halfW - 0.1, roomHeight - 0.2, 1.5));
var wireCurve = new THREE.CatmullRomCurve3(wirePts);
var wirePathGeo = new THREE.TubeGeometry(wireCurve, 20, 0.008, 4, false);
var wirePath = new THREE.Mesh(wirePathGeo, wireMat);
wireGroup.add(wirePath);

var wire2Pts = [];
wire2Pts.push(new THREE.Vector3(-halfW + 0.1, roomHeight - 0.15, 5));
wire2Pts.push(new THREE.Vector3(-halfW + 0.15, roomHeight - 0.4, 3));
wire2Pts.push(new THREE.Vector3(-halfW + 0.1, roomHeight - 0.2, 0));
wire2Pts.push(new THREE.Vector3(-halfW + 0.12, roomHeight - 0.5, -3));
var wire2Curve = new THREE.CatmullRomCurve3(wire2Pts);
var wire2Geo = new THREE.TubeGeometry(wire2Curve, 20, 0.006, 4, false);
wireGroup.add(new THREE.Mesh(wire2Geo, wireMat));

// ============================================================
// LIVING ELEMENTS — the rat and the drip
// ============================================================
// A cellar rat works the base of the left wall: dart, pause, sniff, dart,
// gone. Near-black silhouette — the far fog swallows it at the deep end.
var ratMat = new THREE.MeshStandardMaterial({ color: 0x302b29, roughness: 0.95 });
var ratG = new THREE.Group();ratG.name="dss-cellar-rat";
ratG.visible = false;
scene.add(ratG);
function ratPart(geo, x, y, z, sx, sy, sz) {
var m = new THREE.Mesh(geo, ratMat);
m.position.set(x, y, z); m.scale.set(sx||1, sy||1, sz||1);
ratG.add(m); return m;
}
ratPart(new THREE.SphereGeometry(.075,20,14),0,.062,0,.78,.68,1.48);
[-1,1].forEach(function(side){ratPart(new THREE.SphereGeometry(.048,16,12),side*.035,.045,-.058,.75,.85,1);});
var ratHead=new THREE.Group();ratHead.position.set(0,.053,.109);ratG.add(ratHead);
var ratSkull=new THREE.Mesh(new THREE.SphereGeometry(.042,18,12),ratMat);ratSkull.scale.set(.79,.76,1.15);ratHead.add(ratSkull);
var ratSnout=new THREE.Mesh(new THREE.SphereGeometry(.027,16,10),ratMat);ratSnout.position.set(0,-.009,.045);ratSnout.scale.set(.64,.56,1.4);ratHead.add(ratSnout);
var ratSkin=new THREE.MeshStandardMaterial({color:0x765d54,roughness:.88});
var ratNose=new THREE.Mesh(new THREE.SphereGeometry(.008,12,8),ratSkin);ratNose.position.set(0,-.008,.082);ratHead.add(ratNose);
[-1,1].forEach(function(side){
 var ear=new THREE.Mesh(new THREE.SphereGeometry(.019,14,10),ratMat);ear.position.set(side*.028,.028,-.008);ear.scale.set(1,1,.32);ratHead.add(ear);
 var inner=new THREE.Mesh(new THREE.SphereGeometry(.014,12,8),ratSkin);inner.position.set(side*.028,.028,-.001);inner.scale.set(1,1,.16);ratHead.add(inner);
 var eye=new THREE.Mesh(new THREE.SphereGeometry(.005,12,8),new THREE.MeshStandardMaterial({color:0x090a08,roughness:.22}));eye.position.set(side*.029,.005,.025);ratHead.add(eye);
 var lines=[];for(var wh=0;wh<3;wh++){lines.push(new THREE.Vector3(side*.015,-.01,.061),new THREE.Vector3(side*(.056+wh*.005),-.008+(wh-1)*.009,.068));}ratHead.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(lines),new THREE.LineBasicMaterial({color:0x8d8975,transparent:true,opacity:.45})));
});
var ratFeet=[];
[-1,1].forEach(function(side){[false,true].forEach(function(rear){var foot=new THREE.Group();foot.position.set(side*.043,.032,rear?-.071:.067);var ankle=new THREE.Mesh(new THREE.SphereGeometry(.015,12,8),ratMat);ankle.scale.set(.7,1.2,.8);foot.add(ankle);var paw=new THREE.Mesh(new THREE.SphereGeometry(.013,12,8),ratSkin);paw.position.set(0,-.019,.009);paw.scale.set(.8,.35,1.4);foot.add(paw);ratG.add(foot);ratFeet.push(foot);});});
var ratTail=[],ratTailVecA=new THREE.Vector3(),ratTailVecB=new THREE.Vector3(),ratTailAxis=new THREE.Vector3(0,1,0);
for(var rti0=0;rti0<12;rti0++){var rtSeg=new THREE.Mesh(new THREE.CylinderGeometry(Math.max(.001,.009-rti0*.00065),Math.max(.001,.0096-rti0*.00065),1,7),ratSkin);ratG.add(rtSeg);ratTail.push(rtSeg);}
// Routes are waypoint paths [x,z]. A/B: the left-wall runs. C: breaks cover
// across the open floor — through the bulb's pool — and vanishes under the
// sofa. D/E: re-emerges from under the sofa later (D deep exit, E near exit).
var ratRoutes = {
A: [[-2.8, 4.6], [-2.75, -0.5], [-2.8, -6.5]],
B: [[-2.8, -6.5], [-2.75, -0.5], [-2.8, 4.6]],
C: [[-2.8, 4.6], [-1.6, 3.2], [0.4, 2.2], [2.02, 1.75]],
D: [[2.02, 1.2], [0.2, 0.2], [-1.8, -1.6], [-2.8, -6.3]],
E: [[2.02, 1.9], [0.0, 3.4], [-2.8, 4.6]]
};
var ratState = { phase: 'wait', tNext: 1.3, atSofa: false, pts: null, cum: null, total: 0, traveled: 0, pauseAts: [], pauseUntil: 0, lastT: 0 };

// The drip: ceiling damp over the dark puddle, on a fixed metronomic cycle —
// swell, fall, rings. Everything is a pure function of t so a throttled tab
// can't wedge the state.
var dripMat = new THREE.MeshStandardMaterial({ color: 0x707880, roughness: 0.15, metalness: 0.2, transparent: true, opacity: 0.85 });
var dripDrop = new THREE.Mesh(new THREE.SphereGeometry(0.012, 8, 6), dripMat);
dripDrop.position.set(-0.6, 2.72, 4.0);
scene.add(dripDrop);
var ripMat1 = new THREE.MeshBasicMaterial({ color: 0x8a6a58, transparent: true, opacity: 0, depthWrite: false });
var ripRing1 = new THREE.Mesh(new THREE.RingGeometry(0.085, 0.1, 28), ripMat1);
ripRing1.rotation.x = -Math.PI/2; ripRing1.position.set(-0.6, 0.012, 4.0);
scene.add(ripRing1);
var ripMat2 = ripMat1.clone();
var ripRing2 = new THREE.Mesh(new THREE.RingGeometry(0.085, 0.1, 28), ripMat2);
ripRing2.rotation.x = -Math.PI/2; ripRing2.position.set(-0.6, 0.011, 4.0);
scene.add(ripRing2);

// The Copper smokes. A coal at his hand rises to the mouth, flares, sinks;
// smoke climbs off it into the joists; on the flare his outline catches a
// breath of orange. The arm is a bare cylinder — in silhouette the motion
// is the whole read. All positions are manGroup-local.
var embHandRest = new THREE.Vector3(0.30, 0.78, 0.16);
var embMouth = new THREE.Vector3(0.03, 1.22, 0.14);
var embShoulder = new THREE.Vector3(0.19, 1.02, 0.06);
var emberCoal = new THREE.Mesh(new THREE.SphereGeometry(0.009, 8, 6), new THREE.MeshBasicMaterial({ color: 0xdd5518 }));
manGroup.add(emberCoal);
var emberGlowTex = makeCanvasTexture(32, 32, function(cx, w, h) {
var g = cx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w/2);
g.addColorStop(0, 'rgba(255,140,50,0.95)'); g.addColorStop(0.4, 'rgba(230,90,25,0.35)'); g.addColorStop(1, 'rgba(200,70,15,0)');
cx.fillStyle = g; cx.fillRect(0, 0, w, h);
});
var emberGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: emberGlowTex, transparent: true, opacity: 0.4, depthWrite: false }));
emberGlow.scale.set(0.06, 0.06, 1);
manGroup.add(emberGlow);
var emberLight = new THREE.PointLight(0xff5510, 0.08, 2.0, 2.0);
manGroup.add(emberLight);
var emberArm = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.03, 1, 6), silhouetteMat);
emberArm.castShadow = false;
var emberArmG = new THREE.Group();
emberArmG.add(emberArm);
manGroup.add(emberArmG);
var emberState = { mode: 'rest', start: 0, until: 5.5 };
var embPos = new THREE.Vector3();
var embDir = new THREE.Vector3();
var embUp = new THREE.Vector3(0, 1, 0);
var smokeParts = [];
for (var smi = 0; smi < 14; smi++) {
var smSp = new THREE.Sprite(new THREE.SpriteMaterial({ map: clHazeTex, transparent: true, opacity: 0, depthWrite: false, color: 0x8a8a7c }));
smSp.visible = false;
smSp.userData = { age: -1, life: 0, vy: 0, vz: 0, o: 0, s0: 0, s1: 0, swPh: Math.random()*6.28 };
manGroup.add(smSp);
smokeParts.push(smSp);
}
var smokeNext = 0;
function smokeSpawn(px, py, pz, exhale) {
for (var ssi = 0; ssi < smokeParts.length; ssi++) {
if (smokeParts[ssi].userData.age < 0) {
var ssp = smokeParts[ssi];
ssp.position.set(px, py, pz);
ssp.userData.age = 0;
ssp.userData.life = 5 + Math.random()*1.5;
ssp.userData.vy = exhale ? 0.26 : 0.30;
ssp.userData.vz = exhale ? 0.05 : 0.0;
ssp.userData.o = exhale ? 0.16 : 0.10;
ssp.userData.s0 = exhale ? 0.16 : 0.10;
ssp.userData.s1 = exhale ? 0.75 : 0.5;
ssp.visible = true;
return;
}
}
}

// ============================================================
// ANIMATION
// ============================================================
var clock = new THREE.Clock();
var baseBulbIntensity = 3.8; // was 2.5 — the famous bulb should command its cellar
var baseBulbEmissive = 1.0; // was 0.55
var baseGlowOpacity = 0.1;

function clAnimate() {
clAnimId = requestAnimationFrame(clAnimate);
var t = clStill ? 0.3 : clock.getElapsedTime();

// Breathing light instead of pulsing/flickering
var breath = 0.97 + Math.sin(t * 0.4) * 0.03;
bulbLight.intensity = baseBulbIntensity * breath;
bulbGlass.emissiveIntensity = baseBulbEmissive * breath;
// Haze drifts like still air disturbed
for (var hzi = 0; hzi < (clStill ? 0 : clHaze.length); hzi++) {
  var hzs = clHaze[hzi];
  hzs.position.x += Math.sin(Date.now() * hzs.userData.sp + hzs.userData.ph) * 0.0022;
  hzs.material.rotation += 0.00035;
}
clShaft.material.opacity = 0.045 * breath;
glowSphere.material.opacity = baseGlowOpacity * breath;

// Subtle sway
var sway = Math.sin(t * 0.4) * 0.0015;
bulbSphere.position.x = sway;
bulbLight.position.x = sway;
glowSphere.position.x = sway;
wire.position.x = sway * 0.5;

// Camera drift
camera.position.x = 0.3 + Math.sin(t * 0.12) * 0.017 + Math.sin(t * 0.5) * 0.003;
camera.position.y = 1.5 + Math.sin(t * 0.15) * 0.006 + Math.sin(t * 0.6) * 0.002;

// The drip cycle (3.4s): swell at the ceiling, fall, rings on the puddle
var dc = t % 3.4;
if (dc < 0.55) {
dripDrop.visible = true;
var dsw = 0.4 + (dc/0.55)*0.6;
dripDrop.scale.set(dsw, dsw*1.6, dsw);
dripDrop.position.y = 2.72;
} else {
var dFall = dc - 0.55;
var dy = 2.72 - 4.9*dFall*dFall;
if (dy > 0.02) { dripDrop.visible = true; dripDrop.scale.set(1, 1.75, 1); dripDrop.position.y = dy; }
else { dripDrop.visible = false; }
}
var ripAge = dc - 1.294;
if (ripAge > 0 && ripAge < 1.3) {
var rs1 = 0.18 + ripAge*1.05;
ripRing1.scale.set(rs1, rs1, 1);
ripMat1.opacity = 0.5*(1 - ripAge/1.3);
} else { ripMat1.opacity = 0; }
var rip2Age = ripAge - 0.18;
if (rip2Age > 0 && rip2Age < 1.1) {
var rs2 = 0.14 + rip2Age*0.8;
ripRing2.scale.set(rs2, rs2, 1);
ripMat2.opacity = 0.38*(1 - rip2Age/1.1);
} else { ripMat2.opacity = 0; }
// The bulb's reflection: steady with the bulb's breath, shivering while a ring crosses it
var clRw = (ripAge > 0 && ripAge < 1.3) ? Math.sin(ripAge * 15) * 0.22 * (1 - ripAge / 1.3) : 0;
clRefl.material.opacity = 0.16 * breath * (1 - Math.abs(clRw) * 0.8);
clRefl.scale.set(1 + clRw, 1 - clRw * 0.5, 1);

// The rat: wait → run a waypoint route (with 1-2 sniff-pauses) → gone.
// If the last route ended under the sofa, the next one starts from it.
var rdt = Math.min(Math.max(t - ratState.lastT, 0), 0.05);
ratState.lastT = t;
if (ratState.phase === 'wait') {
if (t > ratState.tNext) {
var ratKeys = ratState.atSofa ? ['D', 'E'] : ['A', 'B', 'C'];
var ratPick = ratKeys[Math.floor(Math.random()*ratKeys.length)];
ratState.atSofa = (ratPick === 'C');
ratState.pts = ratRoutes[ratPick];
ratState.cum = [0];
for (var rci = 1; rci < ratState.pts.length; rci++) {
var rdx = ratState.pts[rci][0] - ratState.pts[rci-1][0];
var rdz = ratState.pts[rci][1] - ratState.pts[rci-1][1];
ratState.cum.push(ratState.cum[rci-1] + Math.sqrt(rdx*rdx + rdz*rdz));
}
ratState.total = ratState.cum[ratState.cum.length-1];
ratState.traveled = 0;
ratState.pauseAts = Math.random() < 0.65
? [ratState.total*(0.2 + Math.random()*0.3), ratState.total*(0.55 + Math.random()*0.3)]
: [ratState.total*(0.25 + Math.random()*0.5)];
ratState.phase = 'run';
ratG.visible = true;
}
} else if (ratState.phase === 'run') {
ratState.traveled += 2.3 * rdt;
if (ratState.traveled >= ratState.total) {
ratState.phase = 'wait';
// Emerge from under the sofa a touch sooner than a fresh wall visit
ratState.tNext = t + (ratState.atSofa ? 4 + Math.random()*6 : 7 + Math.random()*9);
ratG.visible = false;
} else if (ratState.pauseAts.length && ratState.traveled >= ratState.pauseAts[0]) {
ratState.pauseAts.shift();
ratState.phase = 'pause';
ratState.pauseUntil = t + 0.45 + Math.random()*0.7;
}
} else if (ratState.phase === 'pause') {
if (t > ratState.pauseUntil) ratState.phase = 'run';
}
if (ratG.visible) {
var ratRunning = ratState.phase === 'run';
var rSeg = 1;
while (rSeg < ratState.cum.length - 1 && ratState.cum[rSeg] < ratState.traveled) rSeg++;
var rSegLen = ratState.cum[rSeg] - ratState.cum[rSeg-1];
var rFrac = rSegLen > 0 ? Math.min((ratState.traveled - ratState.cum[rSeg-1]) / rSegLen, 1) : 1;
var rpx = ratState.pts[rSeg-1][0] + (ratState.pts[rSeg][0] - ratState.pts[rSeg-1][0]) * rFrac;
var rpz2 = ratState.pts[rSeg-1][1] + (ratState.pts[rSeg][1] - ratState.pts[rSeg-1][1]) * rFrac;
ratG.position.set(rpx, 0.005 + (ratRunning ? Math.abs(Math.sin(ratState.traveled*22))*.004 : 0), rpz2);
ratG.rotation.y = Math.atan2(ratState.pts[rSeg][0] - ratState.pts[rSeg-1][0], ratState.pts[rSeg][1] - ratState.pts[rSeg-1][1]) + (ratRunning ? Math.sin(ratState.traveled*3)*0.05 : 0);
ratHead.rotation.x=ratRunning?.035:(-.13+Math.sin(t*7)*.025);
ratFeet.forEach(function(foot,i){foot.rotation.x=ratRunning?Math.sin(ratState.traveled*28+(i===0||i===3?0:Math.PI))*.3:0;});
for(var rtj=0;rtj<ratTail.length;rtj++){
 var f=rtj/ratTail.length,nf=(rtj+1)/ratTail.length;
 function tailPoint(v,q){return v.set(Math.sin(t*(ratRunning?5:1.4)-q*3)*.026*q,.025-q*.016,-.10-q*.25);}
 tailPoint(ratTailVecA,f);tailPoint(ratTailVecB,nf);var seg=ratTail[rtj];seg.position.copy(ratTailVecA).add(ratTailVecB).multiplyScalar(.5);var len=ratTailVecB.sub(ratTailVecA).length();seg.scale.y=len;seg.quaternion.setFromUnitVectors(ratTailAxis,ratTailVecB.normalize());
}
}

// The cigarette: rest → raise → drag (flare) → lower → rest (exhale)
if (t > emberState.until) {
if (emberState.mode === 'rest') { emberState.mode = 'raise'; emberState.until = t + 1.3; }
else if (emberState.mode === 'raise') { emberState.mode = 'drag'; emberState.until = t + 1.15; }
else if (emberState.mode === 'drag') { emberState.mode = 'lower'; emberState.until = t + 1.5; }
else {
emberState.mode = 'rest';
emberState.until = t + 5 + Math.random()*6;
smokeSpawn(embMouth.x, embMouth.y + 0.04, embMouth.z + 0.05, true);
smokeSpawn(embMouth.x + 0.03, embMouth.y + 0.02, embMouth.z + 0.08, true);
smokeSpawn(embMouth.x - 0.02, embMouth.y + 0.06, embMouth.z + 0.06, true);
}
emberState.start = t;
}
var embDurs = { raise: 1.3, drag: 1.15, lower: 1.5 };
var embP = emberState.mode === 'rest' ? 0 : Math.min((t - emberState.start) / embDurs[emberState.mode], 1);
var embQ2 = embP*embP*(3 - 2*embP);
var embLerp = emberState.mode === 'raise' ? embQ2 : (emberState.mode === 'drag' ? 1 : (emberState.mode === 'lower' ? 1 - embQ2 : 0));
embPos.copy(embHandRest).lerp(embMouth, embLerp);
var coalI;
if (emberState.mode === 'drag') coalI = 0.6 + Math.sin(embP*Math.PI)*1.6;
else if (emberState.mode === 'rest') coalI = 0.35 + Math.sin(t*1.7)*0.08;
else coalI = 0.45;
emberCoal.position.copy(embPos);
emberCoal.material.color.setRGB(Math.min(1, 0.72 + coalI*0.12), Math.min(1, 0.24 + coalI*0.14), 0.06);
emberGlow.position.copy(embPos); emberGlow.position.z += 0.02;
emberGlow.material.opacity = Math.min(0.95, 0.28 + coalI*0.28);
var embGs = 0.07 + coalI*0.04;
emberGlow.scale.set(embGs, embGs, 1);
emberLight.position.copy(embPos);
emberLight.intensity = 0.05 + coalI*0.22;
embDir.copy(embPos).sub(embShoulder);
var embALen = embDir.length();
emberArmG.position.copy(embShoulder);
emberArmG.quaternion.setFromUnitVectors(embUp, embDir.normalize());
emberArm.scale.set(1, embALen, 1);
emberArm.position.set(0, embALen/2, 0);
// The thin ribbon off the coal, and the drift of every live smoke sprite
if (t > smokeNext) { smokeSpawn(embPos.x, embPos.y + 0.03, embPos.z, false); smokeNext = t + 0.8 + Math.random()*0.5; }
for (var smj = 0; smj < smokeParts.length; smj++) {
var smU = smokeParts[smj].userData;
if (smU.age < 0) continue;
smU.age += rdt;
if (smU.age > smU.life) { smU.age = -1; smokeParts[smj].visible = false; continue; }
var smF = smU.age / smU.life;
smokeParts[smj].position.y += smU.vy * rdt;
smokeParts[smj].position.z += smU.vz * rdt;
smokeParts[smj].position.x += Math.sin(t*0.6 + smU.swPh) * 0.02 * rdt;
var smS = smU.s0 + (smU.s1 - smU.s0) * smF;
smokeParts[smj].scale.set(smS, smS, 1);
smokeParts[smj].material.opacity = smU.o * Math.min(smF/0.15, 1) * (1 - Math.max(0, smF - 0.6)/0.4);
smokeParts[smj].material.rotation += 0.0006;
}

if (typeof dssComposerLocal !== 'undefined' && dssComposerLocal) { dssComposerLocal.render(); } else { renderer.render(scene, camera); }
}

clAnimate();

// ============================================================
// OVERLAYS
// ============================================================

// Vignette
var clVig = document.createElement('div');
clVig.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:9001;background:radial-gradient(ellipse at 45% 45%, transparent 25%, rgba(0,0,0,0.65) 100%);';
