catPart(new THREE.SphereGeometry(0.026, 8, 6), -0.047, 0.014, 0.135, 1, 0.55, 1.3);
catPart(new THREE.SphereGeometry(0.026, 8, 6), 0.047, 0.014, 0.135, 1, 0.55, 1.3);
