var ofSwapPairs=0;
function ofSpineClear(r){return ![[130,170,100,120],[640,200,118,146],[360,430,136,120]].some(function(p){return r.x<p[0]+p[2]+4&&r.x+r.w>p[0]-4&&r.y<p[1]+p[3]+4&&r.y+r.h>p[1]-4;});}
