 '#include <map_fragment>',
 'vec4 swapID=texture2D(ofSwapMask,vUv);',
 'float pairID=(swapID.r*255.0-32.0)/48.0;',
 'float swapElapsed=ofMagicTime-(5.0+pairID*2.7);',
 'if(swapID.a>0.9 && swapElapsed>=0.0){',
 'float swapPeriod=12.0+pairID*3.7;',
 'float age=mod(swapElapsed,swapPeriod);',
 'float swapped=mod(floor(swapElapsed/swapPeriod)+step(0.8,age),2.0);',
 'diffuseColor.rgb=mix(diffuseColor.rgb,texture2D(ofSwapMap,vUv).rgb*diffuse,swapped);',
 'float vanish=age<1.6?abs(age-0.8)/0.8:1.0;',
 'diffuseColor.rgb*=smoothstep(0.0,1.0,vanish);',
 '}',
 'vec4 bookID=texture2D(ofBookMask,vUv);',
 'float seed=bookID.r*255.0;',
 'float pace=mod(floor(seed),4.0)<1.0?3.0+mod(seed*0.173,3.0):8.0+mod(seed*0.731,14.0);',
 'float phase=ofMagicTime*6.283185/pace+seed*2.399;',
 'float blend=0.5+0.5*sin(phase);blend=blend*blend*(3.0-2.0*blend);',
 'float pick=mod(floor(seed),6.0);',
 'vec3 hue=vec3(0.60,0.045,0.12);',
 'if(pick>0.5)hue=vec3(0.015,0.48,0.30);',
 'if(pick>1.5)hue=vec3(0.06,0.16,0.72);',
 'if(pick>2.5)hue=vec3(0.45,0.055,0.62);',
 'if(pick>3.5)hue=vec3(0.68,0.40,0.035);',
 'if(pick>4.5)hue=vec3(0.68,0.09,0.35);',
 'float lum=dot(diffuseColor.rgb,vec3(0.2126,0.7152,0.0722));',
 'float chroma=max(max(diffuseColor.r,diffuseColor.g),diffuseColor.b)-min(min(diffuseColor.r,diffuseColor.g),diffuseColor.b);',
 'vec3 magic=hue*lum*1.3/max(0.01,dot(hue,vec3(0.2126,0.7152,0.0722)));',
