ofVig.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:9001;background:radial-gradient(ellipse at 48% 44%, transparent 30%, rgba(0,0,0,0.6) 100%);';
