    var sootT = cx.createLinearGradient(0, 0, 0, 40); sootT.addColorStop(0, 'rgba(10,6,4,0.35)'); sootT.addColorStop(1, 'rgba(10,6,4,0)'); cx.fillStyle = sootT; cx.fillRect(0, 0, w, 40);
    var scufB = cx.createLinearGradient(0, h - 50, 0, h); scufB.addColorStop(0, 'rgba(20,10,8,0)'); scufB.addColorStop(1, 'rgba(20,10,8,0.45)'); cx.fillStyle = scufB; cx.fillRect(0, h - 50, w, 50);
