    var grease = cx.createLinearGradient(0, h * 0.35, 0, h); grease.addColorStop(0, 'rgba(120,80,20,0)'); grease.addColorStop(1, 'rgba(120,80,20,0.28)'); cx.fillStyle = grease; cx.fillRect(0, 0, w, h);
