    if (!apStill && flickerT <= 0) { var dead = Math.random() < 0.45; tickTroffer.material.color.setHex(dead ? 0x1e1e18 : (Math.random() < 0.5 ? 0x8a8870 : 0xd8d4b0)); flickerT = Math.random() < 0.75 ? 0.05 + Math.random() * 0.25 : 1.5 + Math.random() * 3; }
    // the red neon buzzes
    var buzz = (!apStill && Math.random() < 0.03) ? 0.35 : 1.0;
    neonFlick = neonFlick + (buzz - neonFlick) * 0.5;
    subSign.material.opacity = 0.55 + 0.45 * neonFlick; subGlow.intensity = 0.6 * neonFlick; neonSprite.material.opacity = 0.6 * neonFlick;
    apSheen.material.opacity = 0.075 + 0.035 * neonFlick;
    // bunting lifts in the draught from the concourse; pendants swing a little
    for (var b = 0; b < bunting.length; b++) bunting[b].m.rotation.z = Math.sin(t * 1.4 + bunting[b].ph) * 0.22;
    for (var pg = 0; pg < pendantGroups.length; pg++) { var P = pendantGroups[pg]; P.g.rotation.x = Math.sin(t * 0.9 + P.ph) * 0.03; P.g.rotation.z = Math.cos(t * 0.7 + P.ph) * 0.025; }

    // departures: a row flips over now and then, seen on the pub's TV
    if (flipRow < 0) { nextFlip -= dt; if (nextFlip <= 0) { flipRow = Math.floor(Math.random() * departuresRows.length); flipT = 0; } }
    else {
      flipT += dt * 1.6; drawDepartures(flipRow, Math.min(1, flipT)); departuresTex.needsUpdate = true;
      if (flipT >= 1.2) { flipRow = -1; nextFlip = 2 + Math.random() * 4; drawDepartures(-1, 1); departuresTex.needsUpdate = true; }
    }

    // people shift in their seats
    for (var f = 0; f < figures.length; f++) {
      var fg = figures[f]; fg.phase += fg.speed * dt;
      fg.sprite.position.x = fg.baseX + Math.sin(fg.phase) * fg.amt;
      fg.sprite.position.y += (Math.sin(fg.phase * 0.7) * 0.004 - (fg.sprite.position.y - (fg.sprite.scale.y > 1.5 ? 0.9 : 0.72))) * 0.1;
    }

    raycaster.setFromCamera(mouseNDC, camera);
    var hits = mouseMoved ? raycaster.intersectObjects(clickableObjects) : [];
    var hv = hits.length ? venueData.get(hits[0].object) : null;
    if (hv !== hoveredVenue) {
      hoveredVenue = hv;
      if (hv) { tooltip.textContent = hv.name; tooltip.classList.add('visible'); apWrap.style.cursor = 'pointer'; }
      else { tooltip.classList.remove('visible'); apWrap.style.cursor = ''; }
    }

