      var lg = ctx.createLinearGradient(lip, 0, w, 0); lg.addColorStop(0, 'rgba(240,246,255,0)'); lg.addColorStop(0.45, 'rgba(242,247,255,0.85)'); lg.addColorStop(0.8, 'rgba(250,252,255,1)'); lg.addColorStop(1, 'rgba(250,252,255,0.2)');
