    sg.addColorStop(0, 'rgba(240,150,70,0.5)'); sg.addColorStop(0.3, 'rgba(200,110,50,0.22)'); sg.addColorStop(1, 'rgba(120,60,30,0)');
    ctx.fillStyle = sg; ctx.fillRect(0, 0, w, h);
