    for (var i = 0; i < 14; i++) {
      ctx.fillStyle = 'rgba(30,18,22,0.5)'; ctx.beginPath(); ctx.ellipse(Math.random() * w, h * 0.5 + Math.random() * h * 0.06, 80 + Math.random() * 260, 3 + Math.random() * 7, 0, 0, 6.3); ctx.fill();
      ctx.fillStyle = 'rgba(220,120,60,0.18)'; ctx.beginPath(); ctx.ellipse(Math.random() * w, h * 0.53 + Math.random() * h * 0.04, 60 + Math.random() * 200, 2 + Math.random() * 4, 0, 0, 6.3); ctx.fill();
    }
