      for (var k = 0; k < 20; k++) { ctx.fillStyle = 'rgba(60,40,24,' + Math.random() * 0.3 + ')'; ctx.beginPath(); ctx.arc(x + Math.random() * bw, Math.random() * h, 1 + Math.random() * 6, 0, 6.3); ctx.fill(); }
      if (Math.random() < 0.3) { ctx.strokeStyle = 'rgba(30,20,12,0.5)'; ctx.lineWidth = 1.5; ctx.beginPath(); var cx0 = x + Math.random() * bw; ctx.moveTo(cx0, 4); ctx.lineTo(cx0 + (Math.random() - 0.5) * 20, h - 4); ctx.stroke(); }
