    for (var p = 0; p < 900; p++) { var pv = 60 + Math.random() * 100; ctx.fillStyle = 'rgb(' + Math.floor(pv) + ',' + Math.floor(pv * 0.85) + ',' + Math.floor(pv * 0.65) + ')'; ctx.beginPath(); ctx.ellipse(Math.random() * w, Math.random() * h, 1 + Math.random() * 4, 1 + Math.random() * 3, Math.random() * 3, 0, 6.3); ctx.fill(); }
