    var inner = new THREE.PointLight(0xf5d070, 2.4, 16, 2); inner.position.set(MX, MY + 1.2, MZ - 2.2); scene.add(inner);
    window.__mouthLight = inner;
    window.__mouthHalo = halo(255, 170, 90, 8, MX, MY + 1.5, MZ + 0.6, 0.7);
    halo(255, 150, 70, 24, MX, MY + 1.5, MZ + 1.4, 0.24);
    var glowPlane = new THREE.Mesh(new THREE.PlaneGeometry(2.8, 2.6), new THREE.MeshBasicMaterial({ color: 0xc07030, transparent: true, opacity: 0.6, depthWrite: false })); glowPlane.position.set(MX, MY + 1.5, MZ - 6.6); scene.add(glowPlane);
