var pyBtn = document.createElement('div');
pyBtn.textContent = 'CLIMB TO THE MOUTH';
pyBtn.style.cssText = 'position:fixed;bottom:60px;left:50%;transform:translateX(-50%);padding:14px min(36px, 8vw);white-space:nowrap;max-width:calc(100vw - 16px);box-sizing:border-box;font:16px "Courier New",monospace;color:rgba(214,158,96,0.85);border:1px solid rgba(214,158,96,0.3);letter-spacing:min(4px, 0.9vw);cursor:pointer;z-index:9004;background:transparent;opacity:0;transition:opacity 2s ease;';
setTimeout(function() { pyBtn.style.opacity = '1'; }, 2200);
