var pcStamp = document.createElement('div');
pcStamp.textContent = 'BABYLON';
pcStamp.style.cssText = 'position:absolute;top:18px;right:24px;font:14px "Courier New",monospace;color:rgba(46,40,35,0.78);letter-spacing:2px;pointer-events:none;z-index:9002;';
pcWrap.appendChild(pcStamp);
var pcLoc = document.createElement('div');
pcLoc.classList.add('dss-room-caption');
pcLoc.textContent = 'THE PLAIN OF CHEBAR';
pcLoc.style.cssText = 'position:absolute;bottom:18px;left:50%;transform:translateX(-50%);font:12px "Courier New",monospace;color:rgba(46,40,35,0.72);letter-spacing:2px;pointer-events:none;z-index:9002;';
pcWrap.appendChild(pcLoc);
var pcTip = document.createElement('div');
pcTip.style.cssText = 'position:fixed;padding:6px 14px;background:rgba(240,238,234,0.94);border:1px solid rgba(62,54,48,0.45);font:italic 13px Georgia,serif;color:#2a2420;pointer-events:none;opacity:0;transition:opacity 0.3s;z-index:9003;';
