      near.forEach(function(nb) { if (nb[1] > a) { ctx.beginPath(); ctx.moveTo(pts[a][0], pts[a][1]); var mx = (pts[a][0] + pts[nb[1]][0]) / 2 + (Math.random() - 0.5) * 16, my = (pts[a][1] + pts[nb[1]][1]) / 2 + (Math.random() - 0.5) * 16; ctx.quadraticCurveTo(mx, my, pts[nb[1]][0], pts[nb[1]][1]); ctx.stroke(); } });
