      fogSprites.push({ sprite: sp, x0: sp.position.x, z0: sp.position.z, dx: Math.cos(a) * sp2, dz: Math.sin(a) * sp2, sway: rand(0, 6.3), swaySpeed: rand(0.0006, 0.002), swayAmt: rand(0.4, 1.6), reach: rand(6, 16), t: rand(0, 1000) });
