  addFog(dust, 46, -60, 60, 0.2, 2.0, -120, 12, 6, 22, 0.14, 0.3, 0.3);
  addFog(whiteHaze, 30, -90, 90, 1.5, 7, -200, -20, 20, 70, 0.1, 0.22, 0.28);
  addFog(violetHaze, 16, -180, 20, 6, 30, -420, -180, 60, 160, 0.08, 0.18, 0.3);
  addFog(riverMist, 22, -60, -10, 0.1, 1.2, -140, 4, 5, 14, 0.12, 0.24, 0.3);
