  pcSheen.rotation.order = 'YXZ'; pcSheen.rotation.x = -Math.PI / 2; pcSheen.rotation.y = Math.atan2(6 - BR.x, 8 - BR.z);
  pcSheen.position.set(2.0, plainY(2.0, -18) + 0.2, -18); scene.add(pcSheen);
