    // the woman rocks with the washing: forward over the water and back, a little lift at the turn
    if (washer) { var wk = Math.sin(t * 1.45); washer.position.x = washer.userData.x0 - 0.03 * (wk + 1); washer.position.y = washer.userData.y0 - 0.012 * (wk + 1); }
