    var g=c.createLinearGradient(0,0,0,H);
    g.addColorStop(0,dim?'#0d1522':'#19202e');g.addColorStop(.6,dim?'#333645':'#686075');g.addColorStop(1,dim?'#7b717b':'#c6a393');
    c.fillStyle=g;c.fillRect(0,0,W,H);
